func (q *Queries) PointsHistory(ctx context.Context, arg PointsHistoryParams) ([]PointsHistoryRow, error) {
	rows, err := q.db.Query(ctx, pointsHistory,
		arg.HasCursor,
		arg.AfterAt,
		arg.AfterID,
		arg.RowLimit,
		arg.UserID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PointsHistoryRow{}
	for rows.Next() {
		var i PointsHistoryRow
		if err := rows.Scan(
			&i.GroupID,
			&i.Points,
			&i.Kind,
			&i.Reason,
			&i.RequestedPoints,
			&i.ExpiresOn,
			&i.CreatedAt,
			&i.OrderNumber,
			&i.Expired,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

