const requestNewsletterConfirm = `-- name: RequestNewsletterConfirm :one
INSERT INTO newsletter_confirmations (email, digest, expires_at)
SELECT $1::text,
       $2::bytea,
       now() + $3::interval
WHERE NOT EXISTS (
    SELECT 1 FROM newsletter_subscribers s
    WHERE lower(s.email) = lower($1::text)
      AND s.unsubscribed_at IS NULL
)
ON CONFLICT (lower(email)) DO UPDATE
    SET digest     = EXCLUDED.digest,
        expires_at = EXCLUDED.expires_at,
        created_at = now()
RETURNING id
`

type RequestNewsletterConfirmParams struct {
	Email  string
	Digest []byte
	Ttl    pgtype.Interval
}

// Zero rows means "send nothing", and the way to get there is the WHERE NOT
// EXISTS: the address is already an active subscriber. The ON CONFLICT keeps one
