const returnPayoutFacts = `-- name: ReturnPayoutFacts :many
WITH selected AS (
    SELECT r.id, r.order_id, o.user_id, r.status,
           return_refundable_amount(r.id)::bigint AS refundable_cents,
           coalesce(r.card_refund_cents, 0)::bigint AS card_refund_cents,
           coalesce(r.credit_refund_cents, 0)::bigint AS credit_refund_cents
    FROM return_requests r
    JOIN orders o ON o.id = r.order_id
    WHERE r.id = ANY($1::uuid[])
)
SELECT s.id AS return_request_id,
       s.refundable_cents,
       s.card_refund_cents,
       s.credit_refund_cents,
       (s.user_id IS NOT NULL)::boolean AS has_account,
       coalesce((
           SELECT sum(rf.amount_cents)
           FROM refunds rf
           WHERE rf.return_request_id = s.id AND rf.status = 'succeeded'
       ), 0)::bigint AS card_paid_cents,
       coalesce((
           SELECT sum(sc.amount_cents)
           FROM store_credit_entries sc
           WHERE sc.idempotency_key = 'return-credit:' || s.id::text
       ), 0)::bigint AS credit_paid_cents,
       EXISTS (
           SELECT 1 FROM order_events e
           WHERE e.return_request_id = s.id AND e.kind = 'refunded'
       )::boolean AS refund_event_recorded,
       CASE
           -- Erasure detaches the order owner, but deliberately retains the
           -- order's award lot and loyalty account. A money-settled return may
           -- therefore still owe its idempotent clawback after user deletion.
           WHEN s.refundable_cents <= 0 THEN false
           ELSE (
			   return_loyalty_points_allocation(s.id) > 0
               AND EXISTS (
                   SELECT 1 FROM loyalty_entries e
                   WHERE e.order_id = s.order_id AND e.kind = 'award'
               )
               AND NOT EXISTS (
                   SELECT 1 FROM loyalty_entries e
                   WHERE e.return_request_id = s.id AND e.kind = 'clawback'
               )
           )
       END::boolean AS points_outstanding
FROM selected s
ORDER BY s.id
`

type ReturnPayoutFactsRow struct {
	ReturnRequestID     uuid.UUID
	RefundableCents     int64
	CardRefundCents     int64
	CreditRefundCents   int64
	HasAccount          bool
	CardPaidCents       int64
	CreditPaidCents     int64
	RefundEventRecorded bool
	PointsOutstanding   bool
}

// One row per return, carrying its frozen source allocation and exact durable
// settlement. The queue asks for the whole visible set in one call; an approved
// retry asks for its one id through the same projection. Provider attempt state
// is deliberately absent: pending work reuses its key and a known terminal
// generation appends a successor, so neither makes the recovery button unsafe.
func (q *Queries) ReturnPayoutFacts(ctx context.Context, requestIds []uuid.UUID) ([]ReturnPayoutFactsRow, error) {
	rows, err := q.db.Query(ctx, returnPayoutFacts, requestIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReturnPayoutFactsRow{}
	for rows.Next() {
		var i ReturnPayoutFactsRow
		if err := rows.Scan(
			&i.ReturnRequestID,
			&i.RefundableCents,
			&i.CardRefundCents,
			&i.CreditRefundCents,
			&i.HasAccount,
			&i.CardPaidCents,
			&i.CreditPaidCents,
			&i.RefundEventRecorded,
			&i.PointsOutstanding,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const returnQueue = `-- name: ReturnQueue :many
SELECT json_build_object('Rank', return_payout_outstanding(r.id), 'Priority', (r.status = 'requested'), 'At', r.created_at, 'ID', r.id)::text AS page_cursor, r.id, r.status, r.reason, r.created_at, r.decided_at, r.before_shipment,
       o.order_number,
       (SELECT coalesce(sum(rl.quantity), 0) FROM return_request_lines rl
        WHERE rl.return_request_id = r.id)::integer AS units,
       return_refundable_amount(r.id)::bigint AS refundable_cents,
       coalesce((
           SELECT CASE
               WHEN bool_and(w.win = 'within') THEN 'within'
               WHEN bool_and(w.win = 'goodwill') THEN 'goodwill'
               WHEN bool_and(w.win = 'after') THEN 'after'
               WHEN bool_and(w.win = 'undelivered') THEN 'undelivered'
               ELSE 'mixed'
           END
           FROM (
               SELECT return_line_policy_window(r.created_at, sh.delivered_at) AS win
               FROM return_request_lines rl
               LEFT JOIN LATERAL (
                   SELECT s.delivered_at
                   FROM order_shipment_lines osl
                   JOIN order_shipments s ON s.id = osl.shipment_id
                   WHERE osl.order_line_id = rl.order_line_id
                     AND s.order_id = r.order_id
                     AND s.delivered_at IS NOT NULL
                   ORDER BY s.delivered_at DESC
                   LIMIT 1
               ) sh ON true
               WHERE rl.return_request_id = r.id
           ) w
       ), 'undelivered')::text AS rescission_window
FROM return_requests r
JOIN orders o ON o.id = r.order_id
WHERE (NOT $1::boolean OR (return_payout_outstanding(r.id) < $2::boolean)
       OR (return_payout_outstanding(r.id) = $2::boolean AND (r.status = 'requested') < $3::boolean)
       OR (return_payout_outstanding(r.id) = $2::boolean AND (r.status = 'requested') = $3::boolean AND r.created_at < $4::timestamptz)
       OR (return_payout_outstanding(r.id) = $2::boolean AND (r.status = 'requested') = $3::boolean AND r.created_at = $4::timestamptz AND r.id < $5::uuid))
ORDER BY return_payout_outstanding(r.id) DESC, (r.status = 'requested') DESC, r.created_at DESC, r.id DESC
LIMIT $6::integer
`

type ReturnQueueParams struct {
	HasCursor     bool
	AfterRank     bool
	AfterPriority bool
	AfterAt       time.Time
	AfterID       uuid.UUID
	RowLimit      int32
}

type ReturnQueueRow struct {
	PageCursor       string
	ID               uuid.UUID
	Status           string
	Reason           string
	CreatedAt        time.Time
	DecidedAt        pgtype.Timestamptz
	BeforeShipment   bool
	OrderNumber      string
	Units            int32
	RefundableCents  int64
	RescissionWindow string
}

// policy_window is the union of THIS request's returned lines against each
// line's own shipment. A later unrelated parcel on the same order must not
// reopen a window that line already closed. now() would move a filed request
// into a later window the day the staff member opens it.
// Recovery is the only retry door. Rank it before the intake queue and before
// LIMIT, or fifty newer requests can make an older approved-but-unpaid customer
// disappear from every actionable screen.
func (q *Queries) ReturnQueue(ctx context.Context, arg ReturnQueueParams) ([]ReturnQueueRow, error) {
	rows, err := q.db.Query(ctx, returnQueue,
		arg.HasCursor,
		arg.AfterRank,
		arg.AfterPriority,
		arg.AfterAt,
		arg.AfterID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReturnQueueRow{}
	for rows.Next() {
		var i ReturnQueueRow
		if err := rows.Scan(
			&i.PageCursor,
			&i.ID,
			&i.Status,
			&i.Reason,
			&i.CreatedAt,
			&i.DecidedAt,
			&i.BeforeShipment,
			&i.OrderNumber,
			&i.Units,
			&i.RefundableCents,
			&i.RescissionWindow,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

